# Generated by build.py from recipe.yml for recipe http-give-up-within-a-time-budget. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'hang' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/report.txt'), "report ready`n")
[IO.File]::WriteAllText((Join-Path $PWD 'hang/report.txt'), "report ready`n")
[IO.File]::WriteAllText((Join-Path $PWD 'timed.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Runs curl with the arguments after the first two and says whether the whole command,`n# every attempt and every wait, took from MIN to under MAX seconds.`n# Usage: sh timed.sh MIN MAX CURL-ARGUMENTS...`nmin=`$1; max=`$2; shift 2`nstart=`$(date +%s)`ncurl `"`$@`"`ncode=`$?`nend=`$(date +%s)`nelapsed=`$((end - start))`nif [ `"`$elapsed`" -ge `"`$min`" ] && [ `"`$elapsed`" -lt `"`$max`" ]; then`n  echo `"exit `$code within `$min to `$max seconds`"`nelse`n  echo `"exit `$code after `$elapsed seconds`"`nfi`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', '--fault', '"delay;ms=1500"', '--fault', '"error;scheme=http;reply=503"', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --no-progress-meter -f --retry 10 --retry-delay 1 --retry-max-time 5 -w "%{http_code} %{num_retries}\n" http://127.0.0.1:8080/report.txt } finally { Stop-Process $server0 }
